query:
fragment CountrySummary on Country {
  __typename
  code
  displayName: name
}
fragment LanguageDetails on Language {
  code
  name
  native
}
fragment CountryDetails on Country {
  ...CountrySummary
  capital
  currency @skip(if: $hideCurrency)
  continent {
    code
    name
  }
  ... on Country @include(if: $withLanguages) {
    languages {
      ...LanguageDetails
    }
  }
}
query ExploreCountries(
  $primaryCode: ID!
  $secondaryCode: ID! = "DE"
  $filter: CountryFilterInput = { continent: { eq: "EU" } }
  $withLanguages: Boolean! = true
  $hideCurrency: Boolean! = false
) {
  primary: country(code: $primaryCode) {
    ...CountryDetails
  }

  secondary: country(code: $secondaryCode) {
    ...CountryDetails
  }

  matchingCountries: countries(filter: $filter) {
    ...CountrySummary

    languages @include(if: $withLanguages) {
      ...LanguageDetails
    }
  }
}
